    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }
    Map<Integer, Integer> parentMap = new HashMap<>();
    buildParentMap(0, -1, graph, parentMap);
