private static int countDigit(int x) {
    if (x == 1) return 1;
    if (x == 0) return 0;
    int ans = 0;
    for (int d = 1; x >= 10; d *= 10) {
        int tens = x / d;
        int curDigit = x % d;
        if (curDigit == 1) ans += (10 * (tens - 1) + d);
        else ans += 10 * tens;
    }
    return ans;
}

