public static int longestLine(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int maxLength = 0;
    int[][] dp = new int[m][n];

    // Bottom-up approach to fill the DP array
    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            // If the current cell is 1
            if (mat[i][j] == 1) {
                // Initialize maxLength to 1
                maxLength = 1;
                // Check if the cell above is 1, then the continuity continues diagonally
                if (i + 1 < m && mat[i + 1][j] == 1) {
                    dp[i][j] += dp[i + 1][j] + 1;
                }
                // Check if the cell to the left is 1, then the continuity continues horizontally
                if (j + 1 < n && mat[i][j + 1] == 1) {
                    dp[i][j] += dp[i][j + 1] + 1;
                }
                // Check if the cell diagonally up-left is 1, then the continuity continues diagonally
                if (i + 1 < m && j + 1 < n && mat[i + 1][j + 1] == 1) {
                    dp[i][j] += dp[i + 1][j + 1] + 1;
                }
                // Check if the cell diagonally down-left is 1, then the continuity continues diagonally
                if (i - 1 >= 0 && j + 1 < n && mat[i - 1][j + 1] == 1) {
                    dp[i][j] += dp[i - 1][j + 1] + 1;
                }

                // Update maxLength with the current cell's value
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    return maxLength;
}

