    int[] result = new int[mat.length * mat[0].length];
    int row = 0, col = 0;
    int val = 0;
    while (val < result.length) {
        result[val++] = mat[row][col];
        if (row == 0 && col < mat[0].length - 1) {
            col++;
            if (col >= mat[0].length) {
                row++;
                col--;
