public static int findSmallestInteger(int n) {
    if (n <= 9) {
        return -1; // Already the smallest integer greater than n that can be formed using the digits of n.
    }

    int[] digits = new int[10];
    int originalN = n;
    while (originalN != 0) {
        digits[originalN % 10]++;
        originalN /= 10;
    }

    int smallest = 0;
    for (int i = 9; i >= 0; i--) {
        if (digits[i] > 0) {
            smallest = i * (int) Math.pow(10, digits.length - i - 1);
            digits[i]--;
            break;
        }
    }

    for (int i = 0; i < 10; i++) {
        while (digits[i]-- > 0) {
            smallest = smallest * 10 + i;
        }
    }

    return smallest > n ? smallest : -1;
}

