    double slope3 = (y1 - y3) / (x1 - x3);

    // Check if the slopes between any pair of points are not equal
    return slope1 != slope2 && slope1 != slope3 && slope2 != slope3;
}

public static int findNthUglyNumber(int n) {
    int[] factors = {5, 3, 2};
   PriorityQueue<Long> heap = new PriorityQueue<>();
    Set<Long> visited = new HashSet<>();
    heap.offer(1L);
    visited.add(1L);

    int uglyCount = 1;
    long num;

    for (int i = 0; i < n; i++) {
        num = heap.poll();

        for (int factor : factors) {
            long newNum = num * factor;
            if (visited.add(newNum)) {
                heap.offer(newNum);
            }
        }

        uglyCount++;
    }

    return Integer.parseInt(String.valueOf(num));
}

public static int calculateEnergy(String s) {
    int maxEnergy = 0;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    // Check the last substring
    maxEnergy = Math.max(maxEnergy, currentEnergy);

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i *= 10) {
       anoi(n, i, result);
    }
    return result;
}

private static void anoi(int n, int start, List<Integer> result) {
    for (int i = start; i < start * 10 && i <= n; i++) {
        result.add(i);
        anoi(n, i * 10, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueSet = new HashSet<>();
    for (int num : nums) {
        uniqueSet.add(num);
    }
    return uniqueSet.stream().reduce(0, Integer::sum);
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    // This method splits the string by spaces, reverses each word, and then joins them back together with spaces.
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        String reversedWord = new StringBuilder(word).reverse().toString();
        result.append(reversedWord).append(" ");
    }

    // Remove the trailing space
    return result.toString().trim();
}
